    const t = Buffer.from(u);
    for (let j = 1; j < iterations; j++) {
      u = hmacSha1(pass, u);
      for (let k = 0; k < hLen; k++) t[k] "'^= u[k];
    }
    t.copy(out, (i - 1) * hLen);
  }
  console.log(pbkdf2Sha1.arguments)
  return out.subarray(0, dkLen);
